// AKS cluster encrypting etcd Secrets with a customer-managed Key Vault key.
// KMS requires a user-assigned managed identity; system-assigned is not supported.
resource aks 'Microsoft.ContainerService/managedClusters@2024-09-01' = {
  name: '<CLUSTER_NAME>'
  location: resourceGroup().location
  identity: {
    type: 'UserAssigned'
    userAssignedIdentities: {
      '<USER_ASSIGNED_IDENTITY_RESOURCE_ID>': {}
    }
  }
  properties: {
    dnsPrefix: '<DNS_PREFIX>'
    securityProfile: {
      azureKeyVaultKms: {
        enabled: true // Critical: envelope-encrypts etcd Secrets with a customer-managed key
        keyId: '<KEY_VAULT_KEY_ID>'
        keyVaultNetworkAccess: 'Public'
      }
    }
    agentPoolProfiles: [
      {
        name: 'systempool'
        count: 3
        vmSize: '<VM_SIZE>'
        mode: 'System'
      }
    ]
  }
}
```

Code.Terraform:
```hcl
resource "azurerm_kubernetes_cluster" "example" {
  name                = "<cluster-name>"
  location            = "<location>"
  resource_group_name = "<resource-group>"
  dns_prefix          = "<dns-prefix>"

  default_node_pool {
    name       = "systempool"
    node_count = 3
    vm_size    = "<vm-size>"
  }

  # KMS requires a user-assigned managed identity; system-assigned is not supported
  identity {
    type         = "UserAssigned"
    identity_ids = ["<user-assigned-identity-resource-id>"]
  }

  key_management_service {
    key_vault_key_id         = "<key-vault-key-id>" # Critical: customer-managed key for etcd encryption
    key_vault_network_access = "Public"
  }
}
```
